// Regenerate migration 018 after editing supabase/questline-catalog.json.
// IDs are permanent: change titles without renumbering existing objectives.
const fs = require("node:fs");
const path = require("node:path");
const root = path.resolve(__dirname, "..");
const catalog = JSON.parse(
  fs.readFileSync(path.join(root, "supabase/questline-catalog.json"), "utf8"),
);
const quote = (value) =>
  value == null ? "null" : "'" + String(value).replaceAll("'", "''") + "'";
const lines = [
  "-- Generated by scripts/generate-questline-catalog.cjs. Execute after query 017.",
  "-- Never delete progress or import personal objectives as completed missions.",
  "begin;",
];
for (const game of catalog) {
  lines.push(
    "insert into pokeatlas_private.quest_games(game,title,versions,reviewed,source,side_source) values(" +
      [
        quote(game.key),
        quote(game.title),
        quote(JSON.stringify(game.versions)) + "::jsonb",
        game.reviewed ? "true" : "false",
        quote(game.source),
        quote(game.sideSource),
      ].join(",") +
      ") on conflict(game) do update set title=excluded.title,versions=excluded.versions,reviewed=excluded.reviewed,source=excluded.source,side_source=excluded.side_source;",
  );
  if (!game.quests.length) continue;
  lines.push(
    "insert into pokeatlas_private.quest_catalog(game,quest_id,category,title,position,note) values",
  );
  lines.push(
    game.quests
      .map(
        (q, i) =>
          "(" +
          [
            quote(game.key),
            quote(q.id),
            quote(q.category),
            quote(q.title),
            i + 1,
            quote(q.note),
          ].join(",") +
          ")",
      )
      .join(",\n"),
  );
  lines.push(
    "on conflict(game,quest_id) do update set category=excluded.category,title=excluded.title,position=excluded.position,note=excluded.note;",
  );
}
lines.push("notify pgrst,'reload schema';", "commit;", "");
fs.writeFileSync(
  path.join(root, "supabase/migrations/202610280018_questline_catalog.sql"),
  lines.join("\n"),
  "utf8",
);
